window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-b2ee11d387064a20"]={"versions": [{"id": "FIG-b2ee11d387064a20", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des Einzelschritts „Increment Counter“ innerhalb der AUTOSAR-E2E-Protokoll-Bibliothek (E2E Profile 6). Das Diagramm modelliert das Verhalten der Schutz- und Weiterleitungsfunktionen <code>E2E_P06Protect()</code> und <code>E2E_P06Forward()</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>E2E_P06Protect()</code>: Funktionskontext für den Schutz ausgehender Nutzdaten.\n</li><li><code>E2E_P06Forward()</code>: Funktionskontext für das Weiterleiten geschützter Nutzdaten.\n</li><li><code>State-&gt;Counter</code>: Zustandsvariable vom Typ <code>uint8</code> innerhalb der E2E-Profile-6-Zustandsstruktur.\n</li><li>Initialer Startknoten (Initial Node) und Aktivitätsendknoten (Activity Final Node).\n</li><li>Aktionszustand <code>State-&gt;Counter++</code> mit assoziiertem Kommentar-Knoten (Note).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Kontrollfluss startet am initialen Pseudozustand und geht direkt in die Ausführung der Aktion <code>State-&gt;Counter++</code> über. Dabei wird der Sequenzzähler inkrementiert. Nach Ausführung der Aktion terminiert die Aktivität am Aktivitätsendknoten. Die Ausführung erfolgt sequenziell ohne Verzweigungen oder Nebenläufigkeiten.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Gemäß PRS_E2E_00429 ist das Inkrementierungsverhalten für <code>E2E_P06Protect()</code> und <code>E2E_P06Forward()</code> normativ verbindlich. Der Zähler ist als <code>uint8</code> definiert und besitzt einen Wertebereich von 0 bis 255 (0xFF). Bei Erreichen des Maximalwerts 0xFF erfolgt beim nächsten Inkrementieren ein arithmetischer Überlauf (Wrap-Around) auf 0. Implementierer müssen sicherstellen, dass dieser modulo-256-Überlauf ohne Ausnahmebehandlung exakt auf 0 zurücksetzt.</p>"}, {"id": "FIG-ccf8b49a435ebf9c", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des Einzelschritts „Increment Counter“ innerhalb der AUTOSAR-E2E-Protokoll-Bibliothek (E2E Profile 6). Das Diagramm modelliert das Verhalten der Schutz- und Weiterleitungsfunktionen <code>E2E_P06Protect()</code> und <code>E2E_P06Forward()</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>E2E_P06Protect()</code>: Funktionskontext für den Schutz ausgehender Nutzdaten.\n</li><li><code>E2E_P06Forward()</code>: Funktionskontext für das Weiterleiten geschützter Nutzdaten.\n</li><li><code>State-&gt;Counter</code>: Zustandsvariable vom Typ <code>uint8</code> innerhalb der E2E-Profile-6-Zustandsstruktur.\n</li><li>Initialer Startknoten (Initial Node) und Aktivitätsendknoten (Activity Final Node).\n</li><li>Aktionszustand <code>State-&gt;Counter++</code> mit assoziiertem Kommentar-Knoten (Note).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Kontrollfluss startet am initialen Pseudozustand und geht direkt in die Ausführung der Aktion <code>State-&gt;Counter++</code> über. Dabei wird der Sequenzzähler inkrementiert. Nach Ausführung der Aktion terminiert die Aktivität am Aktivitätsendknoten. Die Ausführung erfolgt sequenziell ohne Verzweigungen oder Nebenläufigkeiten.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Gemäß PRS_E2E_00429 ist das Inkrementierungsverhalten für <code>E2E_P06Protect()</code> und <code>E2E_P06Forward()</code> normativ verbindlich. Der Zähler ist als <code>uint8</code> definiert und besitzt einen Wertebereich von 0 bis 255 (0xFF). Bei Erreichen des Maximalwerts 0xFF erfolgt beim nächsten Inkrementieren ein arithmetischer Überlauf (Wrap-Around) auf 0. Implementierer müssen sicherstellen, dass dieser modulo-256-Überlauf ohne Ausnahmebehandlung exakt auf 0 zurücksetzt.</p>"}], "trans": [{"from": "FIG-b2ee11d387064a20", "to": "FIG-ccf8b49a435ebf9c", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
